import React from 'react';
import {View,Text,Pressable,StyleSheet} from 'react-native';
export default function ProductCard({product,primary,dark,onOpen,onAdd,horizontal=false}) {
 return <View style={[styles.card,{backgroundColor:dark?'#292435':'#f7f7f7'},horizontal&&{flexDirection:'row',alignItems:'center',gap:14.4}]}>
  <Pressable accessibilityRole="button" accessibilityLabel={'View '+product.name} onPress={onOpen}><View style={[styles.art,horizontal&&{height:85,width:100},{backgroundColor:dark?'#383248':'#e9e4de'}]}><Text style={{fontSize:48.6}}>{product.icon}</Text></View><Text style={[styles.category,{color:dark?'#b1aac1':'#7f7f7f'}]}>{product.category}</Text><Text style={[styles.name,{color:dark?'#eeebf7':'#2a253a'}]}>{product.name}</Text></Pressable>
  <View style={styles.bottom}><Text style={{color:primary,fontWeight:'700'}}>Rs. {product.price.toLocaleString()}</Text>{onAdd&&<Pressable accessibilityRole="button" accessibilityLabel={'Add '+product.name+' to bag'} onPress={onAdd} style={[styles.add,{backgroundColor:primary}]}><Text style={{color:'white',fontSize:18.9}}>+</Text></Pressable>}</View>
 </View>;
}
