import React from 'react';
import {View,Text,Pressable,StyleSheet} from 'react-native';
export default function ProductCard({product,primary,dark,onOpen,onAdd,horizontal=false}) {
 return <View style={[styles.card,{backgroundColor:dark?'#2d2839':'#f3f3f3'},horizontal&&{flexDirection:'row',alignItems:'center',gap:14.4}]}>
  <Pressable accessibilityRole="button" accessibilityLabel={'View '+product.name} onPress={onOpen}><View style={[styles.art,horizontal&&{height:85,width:100},{backgroundColor:dark?'#3c364c':'#e5e0da'}]}><Text style={{fontSize:48.6}}>{product.icon}</Text></View><Text style={[styles.category,{color:dark?'#ada6bd':'#838383'}]}>{product.category}</Text><Text style={[styles.name,{color:dark?'#eae7f3':'#2e293e'}]}>{product.name}</Text></Pressable>
  <View style={styles.bottom}><Text style={{color:primary,fontWeight:'700'}}>Rs. {product.price.toLocaleString()}</Text>{onAdd&&<Pressable accessibilityRole="button" accessibilityLabel={'Add '+product.name+' to bag'} onPress={onAdd} style={[styles.add,{backgroundColor:primary}]}><Text style={{color:'white',fontSize:18.9}}>+</Text></Pressable>}</View>
 </View>;
}
