import React from 'react';
import {View,Text,Pressable,StyleSheet} from 'react-native';
export default function ProductCard({product,primary,dark,onOpen,onAdd,horizontal=false}) {
 return <View style={[styles.card,{backgroundColor:dark?'#2d2839':'#f3f3f3'},horizontal&&{flexDirection:'row',alignItems:'center',gap:16.8}]}>
