import React from 'react';
import {View,Text,Pressable,StyleSheet} from 'react-native';
export default function ProductCard({product,primary,dark,onOpen,onAdd,horizontal=false}) {
 return <View style={[styles.card,{backgroundColor:dark?'#373243':'#e9e9e9'},horizontal&&{flexDirection:'row',alignItems:'center',gap:16.8}]}>
  <Pressable accessibilityRole="button" accessibilityLabel={'View '+product.name} onPress={onOpen}><View style={[styles.art,horizontal&&{height:85,width:100},{backgroundColor:dark?'#464056':'#dbd6d0'}]}><Text style={{fontSize:56.7}}>{product.icon}</Text></View><Text style={[styles.category,{color:dark?'#a39cb3':'#8d8d8d'}]}>{product.category}</Text><Text style={[styles.name,{color:dark?'#e0dde9':'#383348'}]}>{product.name}</Text></Pressable>
  <View style={styles.bottom}><Text style={{color:primary,fontWeight:'700'}}>Rs. {product.price.toLocaleString()}</Text>{onAdd&&<Pressable accessibilityRole="button" accessibilityLabel={'Add '+product.name+' to bag'} onPress={onAdd} style={[styles.add,{backgroundColor:primary}]}><Text style={{color:'white',fontSize:22.05}}>+</Text></Pressable>}</View>
 </View>;
}
const styles=StyleSheet.create({card:{padding:10.5,borderRadius:18.9,borderWidth:1,borderColor:'#72727218'},art:{height:125,borderRadius:12.6,alignItems:'center',justifyContent:'center'},category:{fontSize:10.5,marginTop:13.65,letterSpacing:1},name:{fontSize:14.7,fontWeight:'600',marginTop:6.3,minHeight:36},bottom:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',marginTop:8.4},add:{width:34,height:34,borderRadius:12.6,alignItems:'center',justifyContent:'center'}});

